'use strict';
const fs = require('fs');
const path = require('path');
const cp = require('child_process');
const root = path.resolve(__dirname, '..', '..');
const child = cp.spawnSync(process.execPath, [path.join(__dirname, 'second-shift-controller-stress.js')], { cwd: root, encoding: 'utf8' });
process.stdout.write(child.stdout || '');
process.stderr.write(child.stderr || '');
const hidden = path.join(root, '.second-shift-stress-report.json');
const visible = path.join(root, 'second-shift-stress-report.json');
if (!fs.existsSync(hidden)) throw new Error('stress report missing');
const report = JSON.parse(fs.readFileSync(hidden, 'utf8'));
fs.copyFileSync(hidden, visible);
console.log('SECOND_SHIFT_STRESS_BLINDSPOTS_BEGIN');
console.log(JSON.stringify(report.blindspots, null, 2));
console.log('SECOND_SHIFT_STRESS_BLINDSPOTS_END');
console.log('SECOND_SHIFT_STRESS_FUZZ_BEGIN');
console.log(JSON.stringify(report.fuzz, null, 2));
console.log('SECOND_SHIFT_STRESS_FUZZ_END');
process.exit(child.status || 0);
